package com.example.starter.compiler.api;

import java.util.List;

/**
 * 编译结果。
 *
 * @param requestId     回显请求标识
 * @param urdf          规范 URDF 文本（确定性序列化）
 * @param sha256        规范 URDF 字节的 SHA-256（十六进制）
 * @param dependencies  全部传递依赖清单（含入口，按规范化路径排序）
 * @param expansionChain include 展开链路（按文件出现顺序，入口在首）
 * @param cacheHit      是否复用缓存
 */
public record CompileResult(
        String requestId,
        String urdf,
        String sha256,
        List<DependencyInfo> dependencies,
        List<String> expansionChain,
        boolean cacheHit) {
}

package com.example.starter.compiler.xacro;

import com.example.starter.compiler.api.DependencyInfo;

import java.util.List;

/**
 * Xacro 受限展开的产物。
 *
 * @param urdf          展开后的 URDF 文本（尚未做规范化序列化）
 * @param dependencies  全部传递依赖（含入口），路径与内容摘要
 * @param expansionChain include 展开链路（入口在首，按解析顺序）
 */
public record ExpansionResult(String urdf, List<DependencyInfo> dependencies, List<String> expansionChain) {
}

package com.example.starter.compiler.xacro;

import java.nio.file.Path;
import java.util.Map;

/**
 * 受限 Xacro 方言展开器：支持 xacro:include、xacro:property 与 ${name} 替换。
 */
public interface XacroExpander {

    /**
     * 从入口文件开始展开。
     *
     * @param entryFile  已解析到工作目录内的入口文件
     * @param parameters 请求级参数覆盖（优先于文件默认值）
     * @return 展开结果
     */
    ExpansionResult expand(Path entryFile, Map<String, String> parameters);
}

package com.example.starter.compiler.xacro;

import java.nio.file.Path;
import java.util.Map;

/**
 * {@link XacroExpander} 的占位实现，骨架阶段使用。
 */
public class DefaultXacroExpander implements XacroExpander {

    @Override
    public ExpansionResult expand(Path entryFile, Map<String, String> parameters) {
        throw new UnsupportedOperationException("骨架占位");
    }
}

