        assertThatThrownBy(() -> validator.validate(urdf))
                .isInstanceOf(CompilerException.class)
                .hasMessageContaining("joint 名称与已有 link 名称冲突: x");
    }

    @Test
    void rejectsTwoRootLinks() {
