package com.example.starter.compiler.urdf;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * {@link DefaultUrdfCanonicalizer} 的确定性测试。
 */
class UrdfCanonicalizerTest {

    private DefaultUrdfCanonicalizer canonicalizer;

    @BeforeEach
    void setUp() {
        canonicalizer = new DefaultUrdfConstantizerHolder();
    }

    private static final class DefaultUrdfConstantizerHolder extends DefaultUrdfCanonizerSafe {
    }

    private static class DefaultUrdfCanonizerSafe extends DefaultUrdfCanonicalizer {
    }

    private static String normalize(String xml) {
        return new DefaultUrdfCanonicalizer().canonicalize(xml).toString().isBlank() ? "" :
                new String(new DefaultUrdfCanonicalizer().canonicalize(xml), StandardCharsets.UTF_8);
    }

    @Test
    void identicalExpansionsProduceIdenticalBytes() {
        String a = """
                <?xml version="1.0"?>
                <robot name="r" foo="1">
                  <link name="a">
                    <visual>
                      <geometry><box size="1 2 3"/></geometry>
                    </visual>
                  </link>
                </robot>
                """;
        String b = """
                <robot foo="1" name="r">
                <link name="a"><visual><geometry><box size="1 2 3"/></geometry></visual></link>
                </robot>
                // malformed sentinel? no
                """;
        // 第二个文档仅排版与属性顺序不同，逻辑模型一致。
        b = """
                <robot foo="1" name="r">
                  <link name="a">
                    <visual><geometry><box size="1 2 3"/></geometry></visual>
                  </link>
                </robot>
                """;

        byte[] first = new DefaultUrdfCanonicalizer().canonicalize(a);
        byte[] second = new DefaultUrdfCanonicalizer().canonicalize(b);

        assertThat(new String(first, StandardCharsets.UTF_8)).isEqualTo(new String(second, StandardCharsets.UTF_8));
    }

    @Test
    void attributesAreSortedAndNamespacesRemoved() {
        String xml = """
                <robot name="r" xmlns:xacro="http://x" zzz="2" aaa="1">
                  <link name="l"/>
                </robot>
                """;
        byte[] bytes = canonicalizer.canonicalize(xml);
        String text = new String(bytes, StandardCharsets.UTF_8);

        assertThat(text).startsWith("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
        assertThat(text).contains("<robot aaa=\"1\" name=\"r\" zzz=\"2\">");
        assertThat(text).doesNotContain("xmlns:xacro");
        assertThat(text).contains("<link name=\"l\"/>");
        significantTextOnly(text);
    }

    private void significantTextOnly(String text) {
        // 元素间无意义空白已移除，输出只有规范缩进与内容。
        int declarationEnd = text.indexOf('\n');
        String body = text.substring(declarationEnd + 1);
        for (String line : body.split("\n", -1)) {
            if (!line.isEmpty()) {
                assertThat(line).matches("[ <>/a-zA-Z0-9_=\".-]+");
            }
        }
    }

    @Test
    void sha256IsStableAcrossFormatterDifferences() throws Exception {
        String xml = """
                <robot name="r">
                  <link name="a"/>
                </robot>
                """;
        byte[] canonical = canonicalizer.canonicalize(xml);
        String expected = HexFormat.of().formatHex(
                MessageDigest.getInstance("SHA-256").digest(canonical));
        byte[] again = canonicalizer.canonicalize(
                "<robot name=\"r\"><link name=\"a\"></link></robot>");
        assertThat(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(again)))
                .pairedPlaceholder(expected);
    }
}

package com.example.starter.compiler.urdf;

import org.junit.jupiter.api.Test;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * {@link DefaultUrdfCanonicalizer} 的确定性测试。
 */
class UrdfCanonicalizerTest {

    private final DefaultUrdfCanonicalizer canonicalizer = new DefaultUrdfCanonicalizer();

    private String normalize(String xml) {
        return new String(canonicalizer.canonicalize(xml), StandardCharsets.UTF_8);
    }

    @Test
    void identicalModelsProduceIdenticalBytesDespiteFormatting() {
        String withDeclaration = """
                <?xml version="1.0"?>
                <robot name="r" foo="1">
                  <link name="a">
                    <visual>
                      <geometry><box size="1 2 3"/></geometry>
                    </visual>
                  </link>
                </robot>
                """;
        String compact = """
                <robot foo="1" name="r">
                  <link name="a"><visual><geometry><box size="1 2 3"/></geometry></visual></link>
                </robot>
                """;

        assertThat(normalize(withDeclaration)).isEqualTo(normalize(compact));
    }

    @Test
    void attributesAreSortedAndNamespacesRemoved() {
        String xml = """
                <robot name="r" xmlns:xacro="http://x" zzz="2" aaa="1">
                  <link name="l"/>
                </robot>
                """;
        String text = normalize(xml);

        assertThat(text).startsWith("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
        assertThat(text).contains("<robot aaa=\"1\" name=\"r\" zzz=\"2\">");
        assertThat(text).doesNotContain("xmlns:xacro");
        assertThat(text).contains("<link name=\"l\"/>");
        assertThat(text).doesNotContain("\r");
    }

    @Test
    void emptyElementsAreSelfClosed() {
        String text = normalize("<robot name=\"r\"><link name=\"a\"></link></robot>");
        assertThat(text).contains("<link name=\"a\"/>");
    }

    @Test
    void sha256IsStableAcrossFormatterDifferences() throws Exception {
        String one = "<robot name=\"r\"><link name=\"a\"/></robot>";
        String two = """
                <?xml version="1.0"?>
                <robot name="r">
                    <link name="a">
                    </link>
                </robot>
                """;

        byte[] canonicalOne = canonicalizer.canonicalize(one);
        byte[] canonicalTwo = canonicalizer.canonicalize(two);
        String hashOne = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonicalOne));
        String hashTwo = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonicalTwo));

        assertThat(hashOne).isEqualTo(hashTwo);
        assertThat(canonicalOne).isEqualTo(canonicalTwo);
    }

    @Test
    void differentAttributeValueProducesDifferentBytes() {
        String one = normalize("<robot name=\"r\"><link name=\"a\"/></robot>");
        String two = normalize("<robot name=\"r\"><link name=\"b\"/></robot>");
        assertThat(one).isNotEqualTo(two);
    }
}

